try{const s=JSON.parse(localStorage.getItem('api-courier-v1'));if(s){completed=Array.isArray(s.completed)?s.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<3):[];completed=[...new Set(completed)];level=Number.isInteger(s.level)&&s.level>=0&&s.level<3?s.level:0;drafts=s.drafts&&typeof s.drafts==='object'?s.drafts:{}}}catch{}
function save(){try{localStorage.setItem('api-courier-v1',JSON.stringify({completed,level,drafts}))}catch{}}
function progress(){document.querySelectorAll('[data-level]').forEach(b=>{const n=+b.dataset.level;b.classList.toggle('active',n===level);b.classList.toggle('done',completed.includes(n));b.setAttribute('aria-current',n===level?'step':'false')});$('#deliveryCount').textContent=completed.length;$('#xp').textContent=completed.length*100+' XP'}
function load(n){if(running)return;level=n;const m=missions[n];$('#concept').textContent=m.concept;$('#missionTitle').textContent=m.title;$('#missionDescription').textContent=m.description;$('#task').textContent=m.task;$('#code').value=typeof drafts[n]==='string'?drafts[n]:m.starter;$('#hint').textContent=m.hint;$('#hint').hidden=true;$('#hintButton').textContent='Show hint';$('#hintButton').setAttribute('aria-expanded','false');$('#nextButton').hidden=true;$('#feedbackLabel').textContent='DISPATCH NOTES';$('#feedback').textContent='Change the code, then run your delivery. There’s no timer.';$('.feedback-area').classList.remove('success','error');$('#trace').textContent='Your request details will appear here.';$('#responseBadge').textContent='Not sent yet';$('#worldState').textContent='Awaiting your request';position=.14;progress();save()}
$('#code').addEventListener('input',()=>{drafts[level]=$('#code').value;save()});$('#code').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('  ',a,b,'end');drafts[level]=e.target.value;save()}if((e.metaKey||e.ctrlKey)&&e.key==='Enter')run()});
document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>load(+b.dataset.level));$('#hintButton').onclick=()=>{const h=$('#hint');h.hidden=!h.hidden;$('#hintButton').textContent=h.hidden?'Show hint':'Hide hint';$('#hintButton').setAttribute('aria-expanded',String(!h.hidden))};$('#resetCode').onclick=()=>{delete drafts[level];$('#code').value=missions[level].starter;save()};$('#nextButton').onclick=()=>{if(level<2)load(level+1);else load(0)};$('#resetProgress').onclick=()=>{if(running)return;completed=[];drafts={};load(0)};
$('#aboutButton').onclick=()=>$('#about').showModal();$('#about').addEventListener('close',()=>$('#aboutButton').focus({preventScroll:true}));$('#closeAbout').onclick=()=>$('#about').close();$('#about').addEventListener('click',e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
