function sample(frames,t,key){if(!frames?.length)return 0;const duration=frames.at(-1).time||1,tick=t%duration;let a=frames[0],b=a;for(let i=1;i<frames.length;i++){b=frames[i];if(tick<=b.time)break;a=b}const p=b.time===a.time?0:(tick-(a.time||0))/(b.time-(a.time||0));return (a[key]||0)+((b[key]||0)-(a[key]||0))*Math.max(0,Math.min(1,p))}
let previousMode='idle';function drawPip(x,y,size,now){if(!rig)return;const mode=paused?previousMode:walk?'walk':celebration>0&&now-celebration<1100?'celebrate':running?'wait':'idle';previousMode=mode;const anim=rig.animations[mode]?.bones||{},t=now/1000,transforms={};ctx.save();ctx.translate(x,y);ctx.scale(size,-size);if(walk&&position>.5){}for(const b of rig.bones){const a=anim[b.name]||{},ang=(b.rotation||0)+sample(a.rotate,t,'value'),px=(b.x||0)+sample(a.translate,t,'x'),py=(b.y||0)+sample(a.translate,t,'y');const m=new DOMMatrix().translate(px,py).rotate(ang);transforms[b.name]=b.parent?transforms[b.parent].multiply(m):m}for(const s of rig.slots){if(s.name==='parcel'&&level===0&&!completed.includes(0)&&position<.5)continue;const region=rig.skins[0].attachments[s.name][s.attachment],im=parts[region.path];if(!im)continue;const m=transforms[s.bone];ctx.save();ctx.transform(m.a,m.b,m.c,m.d,m.e,m.f);ctx.translate(region.x||0,region.y||0);ctx.scale(1,-1);ctx.drawImage(im,-region.width/2,-region.height/2,region.width,region.height);ctx.restore()}ctx.restore()}
let last=0,animationTime=0;function draw(now){requestAnimationFrame(draw);if(now-last<30)return;const elapsed=last?Math.min(now-last,100):0;last=now;if(!paused)animationTime+=elapsed;const w=worldW,h=worldH,ground=h*.76;ctx.clearRect(0,0,w,h);ctx.fillStyle='#cad8c5';ctx.fillRect(0,0,w,h);ctx.fillStyle='#edf0d8';ctx.beginPath();ctx.arc(w*.65,h*.23,28,0,Math.PI*2);ctx.fill();ctx.fillStyle='#adbfaa';ctx.beginPath();ctx.moveTo(0,ground);for(let x=0;x<=w+40;x+=40)ctx.lineTo(x,ground-50-Math.sin(x*.007)*24-Math.cos(x*.014)*16);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.fillStyle='#93ad98';ctx.beginPath();ctx.moveTo(0,ground+10);for(let x=0;x<=w+20;x+=20)ctx.lineTo(x,ground-18-Math.sin(x*.012)*12);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.fillStyle='#bac6a8';ctx.fillRect(0,ground,w,h-ground);ctx.fillStyle='#e6d5ac';ctx.beginPath();ctx.moveTo(0,ground+5);ctx.lineTo(w,ground+5);ctx.lineTo(w,h-36);ctx.lineTo(0,h-36);ctx.fill();ctx.setLineDash([3,8]);ctx.strokeStyle='#b5a77f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.13,ground+15);ctx.lineTo(w*.86,ground+15);ctx.stroke();ctx.setLineDash([]);const bw=Math.min(120,w*.19),bh=h*.31;building(w*.06,ground-bh,bw,bh,'OUTPOST');building(w*.77,ground-bh,bw,bh,'DEPOT');for(let i=0;i<5;i++){const x=w*(.32+i*.075);ctx.strokeStyle='#718b6e';ctx.beginPath();ctx.moveTo(x,ground);ctx.lineTo(x,ground-8-i%2*5);ctx.stroke()}ctx.fillStyle='#284c4120';ctx.beginPath();ctx.ellipse(w*position,ground+9,24,5,0,0,Math.PI*2);ctx.fill();drawPip(w*position,ground+5,Math.min(.75,w/700),animationTime);if(!rig){ctx.fillStyle='#203b3b';ctx.textAlign='center';ctx.font='12px monospace';ctx.fillText('Preparing courier…',w*.48,ground-50)}}requestAnimationFrame(draw);
